import sys

def process_spell():
    lines = sys.stdin.read().splitlines()
    result = []

    for i, line in enumerate(lines):
        stripped_line = line.lstrip()
        if stripped_line.startswith('#'):
            result.append(line)
        else:
            if result and not result[-1].startswith('#'):
                result[-1] += stripped_line
            else:
                result.append(stripped_line)

    for line in result:
        print(line)

process_spell()
